const id = String($('Appel outil').first().json.event_id || '');
const r = $input.first().json || {};
if (!r.ok || !r.data) return [{ json: { resultat: 'Pas de detail disponible pour ' + id + ' (rendez-vous simple ou identifiant inconnu).' } }];
const d = r.data;
const plat = s => String(s || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
const NOMS = { 5066: 'Laurent', 5069: 'Christophe', 9965: 'Axel', 5198: 'Axel' };
const L = [];
L.push('Intervention ' + (d.reference || id) + ' : ' + [d.type && (d.type.name || d.type), plat(d.title)].filter(Boolean).join(' : '));
if (d.heureParis) L.push('Date : ' + d.dateParis + ' ' + d.heureParis + ' (' + d.horaireLibelle + ')');
if (d.client) L.push('Client : ' + (d.client.name || d.client.displayName || '') + ' (client_id ' + (d.client.id || '') + ')');
const a = d.address || {};
if (a.address) L.push('Adresse : ' + [a.address, [a.zipCode, a.city].filter(Boolean).join(' '), plat(a.additionalLine), plat(a.comments)].filter(Boolean).join(', '));
if (d.users) L.push('Techniciens : ' + [...new Set(d.users.map(u => NOMS[u.id] || u.firstName))].join(', '));
if (d.secondReference) L.push('Devis lie : ' + d.secondReference);
if (d.description) L.push('Description : ' + plat(d.description).slice(0, 1500));
if (d.report) L.push('Compte-rendu : ' + plat(typeof d.report === 'string' ? d.report : JSON.stringify(d.report)).slice(0, 800));
if (d.finished) L.push('Statut : termine');
return [{ json: { resultat: L.join('\n') } }];
